Periodic value noise:
```js
function hash(ix,iy,period,seed){
  ix=((ix%period)+period)%period; iy=((iy%period)+period)%period;
  let h=ix*374761393+iy*668265263+(seed|0)*1442695041;
  h=(h^(h>>13))*1274126177;
  h^=h>>16;
  return (h>>>0)/4294967295;
}
function vnoise(x,y,period,seed){
  const x0=Math.floor(x), y0=Math.floor(y);
  const fx=x-x0, fy=y-y0;
  const ux=fx*fx*(3-2*fx), uy=fy*fy*(3-2*fy);
  const a=hash(x0,y0,period,seed), b=hash(x0+1,y0,period,seed), c=hash(x0,y0+1,period,seed), d=hash(x0+1,y0+1,period,seed);
  return (a+(b-a)*ux)+((c+(d-c)*ux)-(a+(b-a)*ux))*uy;
}
function fbm(x,y,period,seed,oct){
  let v=0,amp=.5,norm=0,f=1;
  for(let i=0;i<oct;i++){v+=amp*vnoise(x*f,y*f,period*f,seed+i*131);norm+=amp;amp*=.5;f*=2;}
  return v/norm;
}
```
